        return checkInt(AppService:GetInstance():GetNextRecoveryTime())
    elseif goodsId == QuestConfMgr:GetTalentTicketId() then
        local talentQuestComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TalentQuestComponent)
        return checkInt(talentQuestComponent:GetTicketsRecoverTime())
    elseif goodsId == ActionUtils.GetDailyQuestTicketId() then
        return ActionUtils.GetTicketsRecoverTime()
    elseif goodsId == Constants.Currency.LadderStruggleTicket then
        local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.LadderStruggleComponent)
        return component:GetTicketsRecoverTime()
    elseif goodsId == Constants.Currency.LadderStruggleSingleTicket then
        local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.LadderStruggleSingleComponent)
        return component:GetTicketsRecoverTime()
    elseif goodsId == checkNumber(ActivityCookingComponent:GetConfigParamsById(ActivityCookingConstants.ParamsDefine.HP_ITEM_ID)) then
        return ActivityCookingComponent.dojo.hpData.lastCdTime
    elseif goodsId == Constants.Currency.Fairyland then
        return FairylandComponent.dojo.hpData.lastCdTime
    elseif goodsId == ParkourGameMgr:GetActivityHPId() then
        return checkNumber(ParkourGameMgr.homeDojo.hpData.lastCdTime)
    elseif goodsId == Constants.Currency.JackpotDungeon then
        local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.HalloweenQuestComponent)
        return comp:GetLastCdTime()
    end
end

