function CommonTipsCountdown:TimeFormat(second)
    local SecondPerMin = 60
    local SecondPerHour = 3600  -- 60*60
    local SecondPerDay = 86400 -- 24*60*60
    
    if second < SecondPerDay then
        local h, m, s
        h = math.floor(second / SecondPerHour)
        m = math.floor((second - SecondPerHour * h) / SecondPerMin)
        s = math.floor(second - SecondPerHour * h - SecondPerMin * m)
        h = h < 10 and "0"..h or h
        m = m < 10 and "0"..m or m
        s = s < 10 and "0"..s or s
        return h..":"..m..":"..s
    end
    
    local result = {}
    if second > SecondPerDay then
        table.insert(result, math.floor(second / SecondPerDay))
        table.insert(result, localize("天"))
        second = second % SecondPerDay
    end
    if second > SecondPerHour then
        table.insert(result, math.floor(second / SecondPerHour))
        table.insert(result, localize("时"))
        second = second % SecondPerHour
    end
    if second > SecondPerMin then
        table.insert(result,math.floor(second / SecondPerMin))
        table.insert(result, localize("分"))
    end
    return table.concat(result)
end

return CommonTipsCountdown